# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::Admission do
  it "fences after an admission and keeps the fence until the next admit!" do
    described_class.admit!(generation: 2)
    described_class.fence!(lock_timeout: 1)
    expect(described_class.current.generation).to be_nil

    described_class.fence!(lock_timeout: 1)
    expect(described_class.current.generation).to be_nil

    described_class.admit!(generation: 3)
    expect(described_class.current.generation).to eq(3)
  end

  # "Fencing waits for writes already admitted, with a lock timeout of 60 s in production use"
  it "sets the production fence lock timeout to 60 seconds and takes the timeout as the lock_timeout keyword" do
    expect(described_class::FENCE_LOCK_TIMEOUT).to eq(60.seconds)
    expect(described_class.method(:fence!).parameters).to include([:key, :lock_timeout])
  end

  # The example's transaction is still open after fence!, so SET LOCAL is
  # still visible here.
  it "fences with the 60 second lock timeout when none is given" do
    described_class.fence!

    expect(ApplicationRecord.connection.select_value("SHOW lock_timeout")).to eq("1min")
    expect(described_class.current.generation).to be_nil
  end

  it "refuses a second row" do
    expect { described_class.insert_all!([{ id: 2 }]) }.to raise_error(ActiveRecord::StatementInvalid, /admission_single_row_check/)
  end

  # admit!(generation: nil) must never fence by accident, and only a positive
  # integer can match a request header, so an invalid value is refused before
  # anything is stored, whether Timekeeping is admitted or fenced.
  it "admit! rejects nil, zero, negative and non-integer generations and leaves the stored generation unchanged" do
    invalid_generations = [nil, 0, -1, "4", 4.0]
    described_class.admit!(generation: 2)

    invalid_generations.each do |generation|
      expect { described_class.admit!(generation:) }.to raise_error(ArgumentError)
      expect(described_class.current.generation).to eq(2)
    end

    described_class.fence!(lock_timeout: 1)
    invalid_generations.each do |generation|
      expect { described_class.admit!(generation:) }.to raise_error(ArgumentError)
      expect(described_class.current.generation).to be_nil
    end
    expect(described_class.count).to eq(1)
  end

  it "raises RecordNotFound from current, fence! and admit! when the row is missing and never creates it" do
    described_class.delete_all

    expect { described_class.current }.to raise_error(ActiveRecord::RecordNotFound)
    expect { described_class.fence!(lock_timeout: 1) }.to raise_error(ActiveRecord::RecordNotFound)
    expect { described_class.admit!(generation: 3) }.to raise_error(ActiveRecord::RecordNotFound)
    expect(described_class.count).to eq(0)
  end

  # The fence stays in place until a later admission
  it "ensure_initial! creates the single row at generation 1 and leaves an existing fenced row fenced" do
    described_class.delete_all

    described_class.ensure_initial!
    expect(described_class.count).to eq(1)
    expect(described_class.current.generation).to eq(1)

    described_class.fence!(lock_timeout: 1)
    described_class.ensure_initial!

    expect(described_class.count).to eq(1)
    expect(described_class.current.generation).to be_nil
  end

  # A database loaded from db/schema.rb has no rows, so db/seeds.rb is what
  # gives a fresh database its admission row.
  it "db/seeds.rb creates the row at generation 1 and leaves an existing fenced row fenced" do
    seeds = Rails.root.join("db/seeds.rb")
    described_class.delete_all

    load seeds
    expect(described_class.count).to eq(1)
    expect(described_class.current.generation).to eq(1)

    described_class.fence!(lock_timeout: 1)
    load seeds

    expect(described_class.count).to eq(1)
    expect(described_class.current.generation).to be_nil
  end
end
